import { useEffect, useId, useRef, useState } from 'react';
import './CommandPalette.css';
// No package exports were provided. This provisional application composition uses
// native dialog and React only; it does not claim a package CommandPalette exists.
export type Command = { id: string; label: string; group: string };
type Props = { open: boolean; commands: Command[]; recentIds: string[]; onClose: () => void; onExecute: (id: string) => void; onRecentIdsChange: (ids: string[]) => void };
export function CommandPalette({ open, commands, recentIds, onClose, onExecute, onRecentIdsChange }: Props) {
 const id = useId();
 const dialog = useRef<HTMLDialogElement>(null);
 const input = useRef<HTMLInputElement>(null);
 const [query, setQuery] = useState('');
 const [active, setActive] = useState(0);
 const normalized = query.trim().toLocaleLowerCase();
 const filtered = commands.filter(command => command.label.toLocaleLowerCase().includes(normalized));
 const recent = normalized ? [] : recentIds.map(recentId => filtered.find(command => command.id === recentId)).filter((command): command is Command => !!command);
 const recentSet = new Set(recent.map(command => command.id));
 const others = filtered.filter(command => !recentSet.has(command.id));
 const groups = [...(recent.length ? [{ label: 'Recent commands', items: recent }] : []),
 ...Array.from(new Set(others.map(command => command.group))).map(group => ({ label: group, items: others.filter(command => command.group === group) }))];
 const flat = groups.flatMap(group => group.items);
 const activeIndex = Math.min(active, Math.max(0, flat.length - 1));
 useEffect(() => { const node = dialog.current!; if (!open) { if (node.open) node.close(); return; } const previous = document.activeElement as HTMLElement | null; setQuery(''); setActive(0); if (!node.open) node.showModal(); input.current?.focus(); return () => { node.close(); previous?.focus(); }; }, [open]);
 const execute = (command: Command) => { onRecentIdsChange([command.id, ...recentIds.filter(recentId => recentId !== command.id)].slice(0,10)); onClose(); onExecute(command.id); };
 return <dialog ref={dialog} className="command-palette" aria-labelledby={id + '-title'} onCancel={event => { event.preventDefault(); onClose(); }}>
 <h2 id={id + '-title'}>Command palette</h2>
 <label className="sr-only" htmlFor={id + '-query'}>Find a command</label>
 <input ref={input} id={id + '-query'} type="text" role="combobox" aria-autocomplete="list" aria-expanded={true} aria-controls={id + '-results'} aria-activedescendant={flat.length ? id + '-result-' + activeIndex : undefined} value={query} placeholder="Find a command…"
 onChange={event => { setQuery(event.target.value); setActive(0); }}
 onKeyDown={event => { if (event.nativeEvent.isComposing) return; if (['ArrowDown','ArrowUp','Home','End'].includes(event.key) && flat.length) { event.preventDefault(); setActive(event.key === 'Home' ? 0 : event.key === 'End' ? flat.length - 1 : (activeIndex + (event.key === 'ArrowDown' ? 1 : -1) + flat.length) % flat.length); } else if (event.key === 'Enter' && flat.length) { event.preventDefault(); execute(flat[activeIndex]); } }} />
 <div id={id + '-results'} role="listbox" aria-label="Commands">{groups.map((group, groupIndex) => <div key={groupIndex} role="group" aria-labelledby={id + '-group-' + groupIndex}><h3 id={id + '-group-' + groupIndex}>{group.label}</h3>{group.items.map(command => { const index = flat.indexOf(command); return <div key={command.id} id={id + '-result-' + index} role="option" aria-selected={index === activeIndex} ref={node => { if (index === activeIndex) node?.scrollIntoView({ block: 'nearest' }); }} onPointerDown={event => event.preventDefault()} onPointerMove={() => setActive(index)} onClick={() => execute(command)}>{command.label}</div>; })}</div>)}</div>
 <p role="status">{flat.length ? flat.length + ' commands available' : 'No matching commands. Try a different search.'}</p>
 <button type="button" onClick={onClose}>Close</button></dialog>;
}
